<?php
require_once dirname(__DIR__).'/src/db.php';
try{require_disposable_test_profile();}catch(Throwable $e){fwrite(STDERR,"REFUSED: ".$e->getMessage()."\n");exit(2);}
$base=rtrim($argv[1]??'','/');if($base===''||!in_array(strtolower((string)parse_url($base,PHP_URL_HOST)),['127.0.0.1','localhost','::1'],true)){fwrite(STDERR,"REFUSED: simulator test requires a loopback scratch server.\n");exit(2);}
$pdo=db();$before=(int)$pdo->query("SELECT COALESCE(MAX(id),0) FROM downlink_commands")->fetchColumn();$command=[PHP_BINARY,dirname(__DIR__).'/tools/simulate_hikers.php','--scenario=reply_lifecycle','--base-url='.$base.'/api'];$pipes=[];$proc=proc_open($command,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__),getenv());if(!is_resource($proc)){fwrite(STDERR,"FAIL start simulator\n");exit(1);}fclose($pipes[0]);$out=stream_get_contents($pipes[1]);fclose($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[2]);$status=proc_close($proc);if($status!==0||!str_contains($out,'Reply lifecycle: created, fetched, sent')){fwrite(STDERR,"FAIL simulator reply lifecycle\n$err$out");exit(1);}echo "PASS simulator reads immediate command, fetches it, and reports sent\n";
$q=$pdo->prepare("SELECT c.created_at,c.fetched_at,c.sent_at,c.status FROM downlink_commands c JOIN hiker_nodes h ON h.id=c.hiker_node_id WHERE c.id>? AND h.node_id='H1' AND c.sequence_number=65000 ORDER BY c.id DESC LIMIT 1");$q->execute([$before]);$row=$q->fetch();if(!$row||$row['status']!=='SENT_TO_BASE'||!$row['created_at']||!$row['fetched_at']||!$row['sent_at']){fwrite(STDERR,"FAIL command lifecycle timestamps/status not persisted\n");exit(1);}echo "PASS command created/fetched/sent lifecycle timestamps persisted\n";
